import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽火革","description":"周易折中 - 泽火革","frontmatter":{"title":"泽火革","description":"周易折中 - 泽火革"},"headers":[],"relativePath":"zh/classics/zhezhong/055.md","filePath":"zh/classics/zhezhong/055.md"}'),h={name:"zh/classics/zhezhong/055.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="泽火革" tabindex="-1">泽火革 <a class="header-anchor" href="#泽火革" aria-label="Permalink to “泽火革”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈革序卦〉：“井道不可不革，故受之以革。井之为物，存之则秽败，易之则清洁，不可不革者也。故井之后，受之以革也。为卦兑上离下，泽中有火也。革，变革也。水火相息之物，水灭火，火涸水，相变革者也。火之性上，水之性下，若相违行，则睽而已；乃火在下，水在上，相就而相克相灭息者也，所以为革也。又二女同居，而其归各异，其志不同，为不相得也，故为革也。”</p><p>革：已日乃孚，元亨利贞，悔亡</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>革，变革也。兑泽在上，离火在下，火燃则水干，水决则火灭。中少二女，合为一卦，而少上中下志不相得，故其卦为革也。变革之初，人未之信，故必已日而后信。又以其内有文明之徳，而外有和说之气，故其占为有所更革，皆大亨而得其正。所革皆当，而所革之悔亡也。一有不正则所革不信、不通，而反有悔矣。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>革者，变其故也。变其故，则人未能遽信，故必已日然后人心信从。元亨利贞，悔亡，毙壊而后革之，革之所以致其通也。故革之而可以大亨，革之而利于正道，则可久而得去故之义无变动之悔，乃悔亡也。革而无甚益，犹可悔也，况反害乎？古人所以重改作也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏简曰 ：已日者，已可革之时也。先时而革，则人疑而罔孚，故已日乃孚。元亨利贞者，谓穷则变，固有大通之道，而利于不失正也。正则其悔亡矣。</p></li><li><p>何氏楷曰 ：已日即六二所谓已日也，乃孚即九三九四九五所谓有孚也，悔亡即九四所谓悔亡也。所以云已日者，变革天下之事不当轻遽，乃能孚信于人，乃难辞也。下三爻方欲革故而为新，故有谨重不轻革之意；上三爻则故者已革而为新矣。九四当上下卦之交，正改命之时，故悔亡独于九四见之，即彖传所云“革而当，其悔乃亡”也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>已日乃孚，李氏、何氏之说为长。盖卦辞、爻辞不应互异也。</p><p>象曰：泽中有火，革；君子以治历明时</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>四时之变革之大者。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>水火相息为革，革变也。君子观变革之象，推日月星辰之迁易，以治历数，明四时之序也。夫变易之道，事之至大，理之至明，迹之至著，莫如四时。观四时而顺变革，则与天地合其序矣。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：历象谓日月星辰也。天地革而四时成，故君子以治历明时也。</p></li><li><p>朱子语类云 ：治历明时，非谓历当改革，盖四时变革中便有个治历明时底道理。</p></li></ul><p>彖曰：革，水火相息，二女同居，其志不相得曰革</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦象释卦名义。大略与睽相似，然以相违而为睽，相息而为革也。息灭，息也，又为生息之义。灭息而后生息也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>泽火相灭息，又二女志不相得，故为革。息为止息，又为生息，物止而后有生，故为生义。革之相息，谓止息也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：兑泽离火，而彖曰“水火”，何也？曰坎兑一也。泽者，水所钟，无水则无泽矣。坎上为云，下为雨。上为云者，泽之气也；下为雨，则泽万物也。故屯、需之坎为云，小畜之兑亦为云。坎为川，大畜之兑亦为川。坎为水，革兑亦为水。坎阳兑阴，阴阳二端，其理则一。知此始可言象矣。</p></li><li><p>朱子语类云 ：革之象不曰“泽在火上”，而曰“泽中有火”。盖水在火上，则水灭了火，不见得火炎则水涸之义。泽中有火，则二物并在，有相息之象。</p></li><li><p>李氏舜臣曰 ：不同行不过，有相离之意，故止于睽；不相得，则不免有相克之事故，至于革。</p></li><li><p>胡氏炳文曰 ：既济水在火上，不曰相息者何也？坎之水动水也，火不能息之；泽之水止水也，止水在上而火炎上，故息。</p></li></ul><p>已日乃孚，革而信之；文明以说，大亨以正，革而当，其悔乃亡</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦德释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>事之变革，人心岂能便信？必终日而后孚。在上者于改为之际，当详告申令，至于已日，使人信之。人心不信，虽强之行，不能成也。先王政令，人心始以为疑者有矣，然其久也必信。终不孚而成善治者，未之有也。文明以说，以卦才言革之道也。离为文明，兑为说。文明则理无不尽，事无不察；说则人心和顺。革而能照察事理，和顺人心，可致大亨而得贞正。如是变革得其至当，故悔亡也。天下之事，革之不得其道，则反致弊害。故革有悔之道，唯革之至当，则新旧之悔皆亡也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：彖未有言悔亡者，唯革言之。革易有悔也，必革而当，其悔乃亡。“当”字即是“贞”字。一有不贞，则有不信、有不通，皆不当者也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>“文明以说，大亨以正”两以字，上句重在“文明”，盖至明则事理周尽，故以此而顺人心，有所更改则无不宜也；下句重在“正”，盖其大亨也以正行之，则无不顺也。凡彖传用“以”字者，文体正倒皆可互用，如“顺以动”及“动而以顺”行，其义一也。</p><p>天地革而四时成，汤武革命，顺乎天而应乎人，革之时大矣哉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言而赞其大。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>推革之道，极乎天地变易，时运终始也。天地阴阳推迁变易而成四时万物，于是生长成终，各得其宜。革而后四时成也。时运既终，必有革而新之者。王者之兴，受命于天，故易世谓之革命。汤武之王，上顺天命，下应人心，顺乎天而应乎人也。天道变改，世故迁易，革之至大也。故赞之曰：“革之时大矣哉！”</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云 ：革是更革之谓，到这里须尽翻转更变一番。所谓上下与天地同流，岂曰小补之哉？小补之者，谓扶衰救弊，逐些补缉，如锢露家事相似。若是更革，则须彻底从新铸造一番，非止补其罅漏而已。</li></ul><p>初九：巩用黄牛之革</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>虽当革时，居初无应，未可有为，故为此象。巩固也。黄，中色；牛，顺物。革所以固物，亦取卦名而义不同也。其占为当坚确固守，而不可以有为。圣人之于变革，其谨如此。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>变革事之大也，必有其时、有其位、有其才。审虑而慎动，而后可以无悔。九以时则初也，动于事初，则无审慎之意，而有躁易之象。以位则下也，无时无援而动于下，则有僭妄之咎，而无体势之重。以才则离体而阳也，离性上而刚，体健皆速于动也。其才如此，有为则凶咎至矣。盖刚不中而体躁，所不足者中与顺也。当以中顺自固，而无妄动则可也。巩，局束也；革，所以包束。黄，中色；牛，顺物。巩用黄牛之革，谓以中顺之道自固，不妄动也。不云吉凶何也？曰妄动则有凶咎，以中顺自固，则不革而已，安得便有吉凶乎？</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>干氏宝曰 ：在革之初，未可以动，故曰“巩用黄牛之革”。</p></li><li><p>刘氏牧曰 ：下非可革之位，初非可革之时，要在固守中顺之道而不敢有革也。</p></li><li><p>吕氏大临曰 ：初九当革之初，居下无位，比于六二，上无正应，虽有刚徳不当自任，惟结六二以自固，故“巩用黄牛之革”。六二居中柔顺，故曰“黄牛”，与遁六二同义。</p></li><li><p>龚氏焕曰 ：《易》言“黄牛之革”者二，遁之六二居中有应，欲遁而不可遁者也；革之初九在下无应，当革而不可革者也。所指虽殊，而意实相类。案：更改之义有取于革者，革鸟兽之皮也。鸟兽更四时，则皮毛改换，尧典“希革毛毨”之类是也。六爻取象于牛虎豹者以此。牛之皮至坚韧，难以更革者也。以之系物则固，故遁二之“执用”者似之；以之裹物则密，故革初之“巩用”者似之。</p></li></ul><p>象曰：巩用黄牛，不可以有为也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>以初九时位才皆不可以有为，故当以中顺自固也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：凡革之道，必须已日然后可以革之也。民固即日而未孚，可遽革之乎？故但可固守中顺，未可大有所为。</p></li><li><p>郑氏汝谐曰 ：居位之下，革之而人未必从。当革之始，遽革而人未必信。固执中顺之道，循理而变通可也。自我有为，不可也。于革之初言之，欲其谨于始也。</p></li></ul><p>六二：已日乃革之，征吉，无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>六二柔顺中正，而为文明之主，有应于上，于是可以革矣。然必已日然后革之，则征吉而无咎。戒占者犹未可遽变也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>以六居二，柔顺而得中正，又文明之主，上有刚阳之君，同徳相应。中正则无偏蔽，文明则尽事理，应上则得权势，体顺则无违悖。时可矣，位得矣，才足矣，处革之至善者也。然臣道不当为革之先，又必待上下之信，故已日乃革之也。如二之才徳所居之地，所逢之时，足以革天下之弊，新天下之治，当进而上辅于君，以行其道，则吉而无咎也。不进则失可为之时，为有咎也。以二体柔而处当位，体柔则其进缓，当位则其处固。变革者事之大，故有此戒。二得中而应刚，未至失于柔也。圣人因其有可戒之疑而明其义耳，使贤才不失可为之时也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：六二以中正之徳，上应九五中正之君，当革之时，卦徳所谓“已日乃孚”是也。故曰“已日乃革之，征吉无咎”。</p></li><li><p>熊氏良辅曰 ：六二为内卦之主，故卦辞之“已日”见之于此。卦曰“已日乃孚”，爻曰“已日乃革”者，孚而后革也。</p></li></ul><p>象曰：已日革之，行有嘉也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>已日而革之，征则吉而无咎者，行则有嘉庆也。谓可以革天下之弊，新天下之事。处而不行，是无救弊济世之心，失时而有咎也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：未当革而遽往，适以滋弊耳，何嘉之有？必往于已日，当革之时，则其行有嘉美之功。行释征字，嘉释吉无咎。</li></ul><p>九三：征凶，贞厉，革言三就，有孚</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>过刚不中，居离之极，躁动于革者也。故其占有“征凶贞厉”之戒。然其时则当革，故至于“革言三就”，则亦有孚而可革也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>九三以刚阳为下之上，又居离之上而不得中，躁动于革者也。在下而躁于变革，以是而行，则有凶也。然居下之上，事苟当革，岂可不为也？在乎守贞正而懐危惧，顺从公论，则可行之不疑。革言，犹当革之论；就成也，合也。审察当革之言，至于三而皆合，则可信也。言重慎之至，能如是，则必得至当，乃有孚也。已可信而众所信也，如此则可以革矣。在革之时，居下之上，事之当革，若畏惧而不为，则失时为害；唯当慎重之至，不自任其刚明，审稽公论，至于三就而后革之，则无过矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕氏大临曰 ：九三居下体之上，自初至三，遍行三爻，革之有渐，革道以成，故曰“革言三就”。至于三，则民信之矣，故有孚。</p></li><li><p>龚氏焕曰 ：九三以过刚之才，躁动以往，则凶。处当革之时，贞固自守，则厉。惟于改革之言，详审三就，则既无躁动之凶，又无固守之厉，得其时宜，所以可革也。</p></li><li><p>胡氏炳文曰 ：以其过刚也，故恐其征而不已则凶；以其不中也，又恐其一于贞固而失变革之义，则厉。故必革之言至于三就，审之屡，则有孚而可革矣。</p></li></ul><p>象曰：革言三就，又何之矣</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>言已审。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>稽之众论，至于三就，事至当也。又何之矣，乃俗语“更何往也”。如是而行，乃顺理时行，非已之私意所欲为也，必得其宜矣。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>徐氏几曰 ：初未可革，二乃革之，三则变革之事成矣。凡事详审至再至三，则止矣，又何往焉。</li></ul><p>九四：悔亡，有孚，改命吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，故有悔。然卦已过中，水火之际，乃革之时，而刚柔不偏，又革之用也，是以悔亡。然又必有孚，然后革乃可获吉。明占者有其徳而当其时，又必有信，乃悔亡而得吉也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>九四，革之盛也。阳刚革之才也，离下体而进上体，革之时也。居水火之际，革之势也，得近君之位，革之任也。下无系应，革之志也。以九居四，刚柔相际，革之用也。四既具此，可谓当革之时也。事之可悔而后革之，革之而当，其悔乃亡也。革之既当，唯在处之以至诚，故有孚则改命吉。改命，改为也，谓革之也。既事当而弊革，行之以诚，上信而下顺，其吉可知。四非中正而至善何也？曰：唯其处柔也，故刚而不过，近而不逼，顺承中正之君，乃中正之人也。《易》之取义无常也，随时而已。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：将革而谋谓之言，革而行之谓之命。</p></li><li><p>陆氏希声曰 ：革而当，故悔亡也。为物所信，则命令不便于民者可改易而获吉。</p></li><li><p>刘氏牧曰 ：成革之体在斯一爻，且自初至三，则革道已成，故下三爻皆以“革”字著于爻辞。至于四，则惟曰“悔亡有孚，改命吉”也。</p></li><li><p>朱子语类 ：问：革下三爻有谨重难改之意，上三爻则革而善。盖事有新故，下三爻则故事未变之时，必当谨审于其先；上三爻则变而为新事矣。 曰：然，乾卦到九四爻谓“乾道乃革”也，是到这处方变。</p></li><li><p>问：革下三爻有谨重难改之意，上三爻则革而善。盖事有新故，下三爻则故事未变之时，必当谨审于其先；上三爻则变而为新事矣。 曰：然，乾卦到九四爻谓“乾道乃革”也，是到这处方变。</p></li><li><p>胡氏炳文曰 ：自三至五皆言有孚，三议革而后孚，四有孚而后改，深浅之序也。五未占而有孚，积孚之素也。</p></li></ul><p>象曰：改命之吉，信志也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>改命而吉，以上下信其志也。诚既至，则上下信矣。革之道，以上下之信为本。不当不孚，则不信；当而不信，犹不可行也，况不当乎？</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰 ：信志，即有孚之谓。革以有孚为本，信足以孚乎人心，则可以改命而得吉矣。</li></ul><p>九五：大人虎变，未占有孚</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>虎，大人之象。变，谓希革而毛毨也。在大人，则自新新民之极，顺天应人之时也。九五以阳刚中正为革之主，故有此象。占而得此，则有此应。然亦必自其未占之时，人已信其如此，乃足以当之耳。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>九五以阳刚之才，中正之徳，居尊位，大人也。以大人之道，革天下之事，无不当也，无不时也。所过变化事理炳著，如虎之文采，故云“虎变”。龙虎大人之象也。变者，事物之变。曰虎何也？曰大人变之，乃大人之变也。以大人中正之道变革之，炳然昭著，不待占决，知其至当，而天下必信也。天下蒙大人之革，不待占决，知其至当而信之也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰 ：革之道久而后信。五与上，其革之成乎？五阳刚中正，居尊而说体尽，革之羙是以未占而有孚也。其文晓然见于天下，道徳之威望而可信。若卜筮罔不是孚，虎变之谓也。</p></li><li><p>龚氏焕曰 ：革以孚信为主，故彖与三四皆以孚为言。至五之“未占有孚”，则不言而信，而无以复加矣。</p></li></ul><p>象曰：大人虎变，其文炳也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>事理明著，若虎文之炳焕，明盛也。天下有不孚乎？</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：虎之斑文大而疏朗，革道已成，事理简明，如虎文之炳然也。</li></ul><p>上六：君子豹变，小人革面，征凶，居贞吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>革道已成，君子如豹之变，小人亦革面以听从矣。不可以往而居正则吉。变革之事，非得已者不可以过，而上六之才亦不可以有行也。故占者如之。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>革之终，革道之成也。君子谓善人良善，则已从革而变，其著见若豹之彬蔚也。小人昏愚难迁者，虽未能心化，亦革其面以从上之教令也。龙虎大人之象，故大人云虎，君子云豹也。人性本善，皆可以变化。然有下愚，虽圣人不能移者。以尧舜为君，以圣继圣，百有馀年，天下被化，可谓深且久矣。而有苗有象，其来格烝又，盖亦革面而已。小人既革其外，革道可以为成也。苟更从而深治之，则为已甚，已甚非道也。故至革之终，而又征则凶也。当贞固以自守，革至于极而不守以贞，则所革随复变矣。天下之事，始则患乎难革，已革则患乎不能守也。故革之终，戒以居贞则吉也。居贞非为六戒乎？曰：为革终言也，莫不在其中矣。人性本善，有不可革者何也？曰：语其性则皆善也，语其才则有下愚之不移。所谓下愚有二焉，自暴也，自弃也。人苟以善自治，则无不可移者，虽昏愚之至，皆可渐摩而进也。唯自暴者拒之以不信，自弃者绝之以不为，虽圣人与居，不能化而入也。仲尼之所谓下愚也。然天下自弃自暴者，非必皆昏愚也，往往强戾而才力有过人者，商辛是也。圣人以其自绝于善，谓之下愚。然考其归，则诚愚也。既曰下愚，其能革面何也？曰：心虽绝于善道，其畏威而寡罪，则与人同也。唯其有与人同，所以知其非性之罪也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：居革之终，变道已成。君子处之，虽不能同九五革命创制，如虎文之彪炳，然亦润色鸿业，如豹文之蔚缛。故曰“君子豹变”也。小人革面者，但能变其颜面容色，顺上而已。革道已成，宜安静守正，更有所征则凶，居而守正则吉。</p></li><li><p>龚氏焕曰 ：九三与上六皆曰“征凶”，而有“贞厉”、“贞吉”之殊者。三之“征凶”，戒其不可妄动也；上之“征凶”，谓事之已革者不可复变也。三当革而未革，故守贞则厉；上已革而当守，故居贞则吉。三革道未成，上革道已成故也。</p></li><li><p>杨氏启新曰 ：革道已成，非上六革之有革之者也。上六特承其重熙累洽之后，治定功成之日耳。若九五，则必尧舜汤武乃足以当之。首创之君，开大型范，耳目一新，若混沌初辟，其文疏朗阔大；继体之后，则渐深䆳遒密耳。周之顽民，既历三纪，世变风移，则“革面”之谓。革而不守以贞，则所变者随复变矣。天下事未革，患其不能革；既革，患其不能守也。故戒以居贞。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>五上两爻相承，虎豹两物相似。程传以君子为被王化之人，似不如孔氏、杨氏以为继体守成之为安也。如文武开基肇造维新，岂非若虎之变而文采焕然者乎？成康继世，礼明乐备，岂非若豹之变而文理繁密者乎？言君子虽稍别于大人，然革道必至此而后为详且备也。至小人革面，方以被王化者言之。所谓“革面”者，亦非但革其面而不能革心之谓，此卦以禽兽取义，凡禽兽之有灵性而近于人者，如猩猩、猿猴之类，皆革其面，故以此为民风丕变之喻。王道之行，则仁义成俗，而心亦无不革矣。不然，何以为必世后仁乎？</p><p>象曰：君子豹变，其文蔚也；小人革面，顺以从君也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>君子从化迁善，成文彬蔚，章见于外也。中人以上莫不变革，虽不移之小人，则亦不敢肆其恶，革易其外以顺从君上之教令，是革面也。至此，革道成矣。小人勉而假善，君子所容也，更往而治之，则凶矣。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：以柔为德，不及九五刚中炳明，故但文章蔚缛，能使小人改观而从也。</p></li><li><p>吕氏大临曰 ：上六与九五皆革道已成之时，虎之文脩大而有理，豹之文密茂而成斑。其文炳然如火之照而易辨也，其文蔚然如草之畅茂而丛聚也。</p></li><li><p>俞氏琰曰 ：小人居革之终，幡然向道以顺从君，无不心悦而诚服。或者乃谓面革而心不革，非也。</p></li></ul><p>总论</p><p>龚氏焕曰：初言“巩用黄牛”，未可有革者也；二言“已日乃革”，不可遽革者也；三言“革言三就”，谨审以为革者也，皆革道之未成也。四言“有孚改命”，则事革矣；五言“大人虎变”，则为圣人之神化矣；上言“君子豹变，小人革面”，则天下为之丕变而革道大成矣。此卦自初至上，明言革道之始终，以及君子、小人之应，可见变革之重要与影响之深远。革者，非徒求变而已，更在于得其时、得其道、得其人，方能使变革之事得以成功，天下得以治平。</p>',120)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
